D[5999]={"^|cff93cceaConsumes 1 Felfury|r\nStrike an enemy with fel fury, dealing (.-) Physical Damage, healing for 25%% of the damage dealt, and cursing them for (.-), increasing ally's attack power against them by (.-)%.\n\n|cffffffffCombo %(Twin Slice, This%):|r Triggers a |cffffffffFelstrike|r on the target%.%s*$","|cff93cceaConsome 1 de Fúria Vil|r\nGolpeia um inimigo com fúria vil, causando {{1}} de dano Físico, curando você em 25% do dano causado e amaldiçoando o alvo durante {{2}}, aumentando em {{3}}% o Poder de Ataque dos aliados contra ele.\n\n|cffffffffCombo (Talho Duplo, esta habilidade):|r ativa um |cffffffffGolpe Vil|r no alvo."}
D[6023]={"^|cff32cd32Generates 1 Felfury|r\nCharge an enemy, dealing (.-) Physical damage%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nAbalança sobre um inimigo, causando {{1}} de dano Físico."}
