D[6027]={"^|cff32cd32Generates 1 Felfury|r\nStrengthen your will, reducing Physical damage taken by (.-)%% for (.-)%.\n\nWhile active, direct damaging abilities heal you for (.-)%% of your maximum health%. Can only occur once every 0%.5 sec%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nFortalece sua vontade, reduzindo o dano Físico recebido em {{1}}% durante {{2}}.\n\nEnquanto estiver ativo, as habilidades de dano direto curam você em {{3}}% de sua vida máxima. Só pode acontecer uma vez a cada 0,5 s."}
D[6028]={"^|cff32cd32Fel Empowerment Ability|r\nSpin in a fury of chaos for (.-), dealing (.-)%% Weapon Damage every (.-) sec with both weapons to up to (.-) nearby enemies%.\n\nYou can move but cannot perform any other abilities, but are immune to roots and slows and loss of control effects%. You cannot be stopped unless disarmed or killed%.\n\n|cFFFFFFFFFel Empowerment|r transforms this spell into |cFFFFFFFFFury Unleashed|r%.%s*$","|cff32cd32Habilidade de Empoderamento Vil|r\nGira em uma fúria de caos durante {{1}}, causando {{2}}% de dano da arma a cada {{3}} s até {{4}} inimigos próximos.\n\nVocê pode se mover, mas não pode usar outras habilidades. É imune aos efeitos de imobilização e redução, assim como a perda do controle. Você só pode ser interrompido se for desarmado ou morto.\n\n|cFFFFFFFFEmpoderamento Vil|r transforma este feitiço em |cFFFFFFFFFúria Desolada|r."}
D[6029]={"^Spin in a fury of chaos for (.-), dealing (.-)%% Weapon Damage every (.-) sec with both weapons to up to (.-) nearby enemies%.\n\nYou can move but cannot perform any other abilities, but are immune to roots and slows and loss of control effects%. You cannot be stopped unless disarmed or killed%.\n\n|cFFFFFFFFFel Empowerment|r transforms this spell into |cFFFFFFFFFury Unleashed|r%.%s*$","Gira em uma fúria de caos durante {{1}}, causando {{2}}% de dano da arma a cada {{3}} s até {{4}} inimigos próximos.\n\nVocê pode se mover, mas não pode usar outras habilidades. É imune aos efeitos de imobilização e redução, assim como a perda do controle. Você só pode ser interrompido se for desarmado ou morto.\n\n|cFFFFFFFFEmpoderamento Vil|r transforma este feitiço em |cFFFFFFFFFúria Desolada|r."}
D[6030]={"^Direct critical strikes now have a (.-)%% chance to trigger a |cffffffffFelstrike|r and generate a |cffffffffFragment of Malice|r%.%s*$","Acertos críticos diretos têm {{1}}% de chance de ativar um |cffffffffGolpe Vil|r e gerar um |cffffffffFragmento de Malícia|r."}
