D[15155]={"^Your next |cFFFFFFFFRuin|r within (.-) is instant cast and deals (.-)%% increased damage%.%s*$","Seu próximo |cFFFFFFFFRuína|r dentro de {{1}} é um lançamento instantâneo e causa o {{2}}% dano adicional."}
