D[44445]={"^Your melee critical strikes now deal an additional (.-) Physical damage and scars enemies for (.-), increasing your allies' attack power against them by (.-)%.%s*$","Agora seus acertos críticos corpo a corpo causam {{1}} de dano Físico adicional e marca os inimigos para {{2}}, aumenta o poder de ataque de seus aliados contra eles em {{3}}."}
D[44446]={"^|cFFFFFFFFTwin Slice|r now deals an additional (.-) Physical damage and scars enemies for (.-), increasing your allies' attack power against them by (.-)%.%s*$","|cFFFFFFFFTalho Duplo|r agora causa um dano Físico adicional de {{1}} e marca os inimigos durante {{2}}, aumenta o poder de ataque de seus aliados contra eles em {{3}}."}
D[44598]={"^Next Smite deals (.-)%% increased damage%.%s*$","O próximo Punição causa dano aumentado em {{1}}%."}
D[45291]={"^|cff32cd32Generates 1 Felfury|r\nUnleash fire on an enemy, increasing their Fire damage taken and their chance to be critically struck with Fire spells from you by (.-)%% for (.-)%.\n\nCan only have 1 |cffffffffBane|r active on a target at a time%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nDesata o fogo sobre um inimigo, aumenta o dano por Fogo que recebem e sua chance de ser atingidos criticamente com feitiços de Fogo por você em {{1}}% durante {{2}}.\n\nSó pode ter ativo 1 |cffffffffAterrar|r por vez em um alvo."}
D[45292]={"^|cff32cd32Generates 1 Felfury|r\nUnleash shadow magic on an enemy, increasing your critical strike chance against them by (.-)%%, but increasing their damage dealt by (.-)%%%. Lasts for 3 critical strikes or (.-)%.\n\nCan only have 1 |cffffffffBane|r active on a target at a time%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nDesata magia sombria sobre um inimigo, aumenta sua chance de causar acerto crítico o alvo em {{1}}% mais também aumenta o dano que este causa em {{2}}%. Dura até 3 acertos críticos ou durante {{3}}.\n\nSó pode ter ativo 1 |cffffffffAterrar|r por vez em um alvo."}
D[45293]={"^|cff32cd32Generates 1 Felfury|r\nUnleash cruel magic on an enemy, allowing you to ignore (.-)%% of their Armor and to see them while stealthed or invisible for (.-)%.\n\nCan only have 1 |cffffffffBane|r active on a target at a time%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nDesata magia cruel sobre um inimigo, permitindo que você ignorar {{1}}% de sua armadura e ver o alvo enquanto estiver em Furtividade ou invisível durante {{2}}.\n\nSó pode ter ativo 1 |cffffffffAterrar|r por vez em um alvo."}
D[46670]={"^Reduces the power cost of abilities of allies within 30 yards by (.-) for (.-), and increases their crit chance by (.-)%% for the duration%.%s*$","Reduz o custo de mana das habilidades dos aliados dentro de 30 metros em {{1}} durante {{2}}, e aumenta sua chance de acerto crítico em {{3}}% durante todo esse tempo."}
D[46671]={"^Increases the melee attack speed of allies within 30 yards by (.-)%% for (.-)%.%s*$","Aumenta a velocidade de ataque corpo a corpo dos aliados dentro de 30 metros em {{1}}% durante {{2}}."}
D[46672]={"^Reduces the damage taken of allies within 30 yards by (.-)%% for (.-)%.%s*$","Reduz o dano recebido por parte dos aliados dentro de 30 metros em {{1}}% durante {{2}}."}
D[47130]={"^Burn an enemy for (.-) Shadowflame Damage over (.-), healing for (.-)%% of the damage dealt and generates (.-) Energy%. \n\nScales with modifiers to |cffffffffSargeron Smite|r%.%s*$","Queima um inimigo durante {{1}} Chute de sombras durante {{2}}, curando em {{3}}% do dano causado e gera {{4}} Energia.\n\nEscala com modificadores para |cffffffffPunição de Sargeron|r."}
D[47512]={"^Deals (.-) Felfire Damage to nearby enemies%.%s*$","causa {{1}} de dano de Fogo Demoníaco os inimigos próximos."}
D[47979]={"^|cff32cd32Consumes 2 Felfury|r\nCharge up a powerful attack over (.-) and then slash in a cone infront of you, dealing Weapon Damage with both weapons%. \n\nThe longer you channel this ability the more damage it deals%. A full channel additionally reduces enemies melee and ranged haste by (.-)%% for (.-) sec%. \n\nCan dodge and parry while channeling%.%s*$","|cff32cd32Consome 2 de Fúria Vil|r\nCarrega um ataque poderoso ao longo de {{1}} e então desfere um golpe em cone à sua frente, causando dano da arma com ambas as armas.\n\nQuanto mais tempo a habilidade for canalizada, maior será o dano. Uma canalização completa também reduz em {{2}}% a aceleração corpo a corpo e à distância dos inimigos durante {{3}} s.\n\nVocê pode se esquivar e aparar enquanto canaliza."}
D[48678]={"^Tuning aura for Felsworn Class%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste da classe Juramentado Vil. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48703]={"^Tuning aura for Felsworn %- Slayer%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste de Juramentado Vil — Assassino. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48704]={"^Tuning aura for Felsworn %- Infernal%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste de Juramentado Vil — Infernal. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48705]={"^Tuning aura for Felsworn %- Tyrant%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste de Juramentado Vil — Tirano. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48906]={"^Summons and dismisses your Felsworn Gnasher%. This mount's speed changes depending on your Riding skill and location%.%s*$","Invoca ou dispensa seu |cffffffffMordedor Devoto Vil|r. A velocidade desta montaria muda de acordo com sua perícia de Montaria e a localização."}
