D[63946]={"^Damage dealt by your |cffffffffRuin|r now increases the duration of |cffffffffBane of Chaos|r and |cffffffffCripple|r on affected enemies by (.-) sec%.\n\nIn addition, casting |cffffffffSargeron Smite|r now reduces the Energy cost and increases the damage of your |cffffffffFelwrath|r and |cffffffffRuin|r by (.-)%% for (.-), stacking 3 times%.%s*$","O dano causado por |cffffffffRuína|r aumenta em {{1}} s a duração de |cffffffffMaldição do Caos|r e |cffffffffEntorpecer|r nos inimigos afetados.\n\nAlém disso, lançar |cffffffffPunição de Sargeron|r reduz o custo de Energia e aumenta em {{2}}% o dano de |cffffffffIra Vil|r e |cffffffffRuína|r durante {{3}}, acumulando até 3 vezes."}
D[64169]={"^Your |cffffffffFel Torpedo|r now reduces all damage taken by (.-)%% for (.-), stacking (.-) times%.%s*$","|cffffffffTorpedo Vil|r agora reduz o dano recebido em {{1}}% durante {{2}}, acumulando-se {{3}} vezes."}
D[64170]={"^Your |cFFFFFFFFChaos Rush|r now reduces all damage taken by (.-)%% for (.-), stacking (.-) times%.%s*$","|cFFFFFFFFInvestida caótica|r agora reduz o dano recebido em {{1}}% durante {{2}}, acumulando-se {{3}} vezes."}
