D[64173]={"^Every 3rd |cffffffffTwin Slice|r or |cffffffffFel Fireball|r within (.-) now generates 1 additional |cff32cd32Felfury|r%.%s*$","Cada 3a |cffffffffTalho Duplo|r ou |cffffffffBola de Fogo Vil|r dentro de {{1}} agora gera 1 |cff32cd32Fúria Vil|r adicional."}
D[64197]={"^While channeling |cffffffffCarve|r, your chance to dodge is now increased by (.-)%% based on how long you channel, up to a maximum of 10%%%.%s*$","Enquanto canais |cffffffffTalhar|r, sua chance de esquiva em {{1}}% aumenta em baseada em quanto tempo canalizar, até um máximo de 10%."}
