D[64674]={"^|cff93cceaConsumes 1 Felfury|r\nStrike an enemy with fel fury, dealing (.-) Physical Damage, healing for 25%% of the damage dealt, and cursing them for (.-), increasing ally's attack power against them by (.-)%.\n\n|cffffffffCombo %(Twin Slice, This%):|r Triggers a |cffffffffFelstrike|r on the target%.%s*$","|cff93cceaConsome 1 de Fúria Vil|r\nGolpeia um inimigo com fúria vil, causando {{1}} de dano Físico, curando você em 25% do dano causado e amaldiçoando o alvo durante {{2}}, aumentando em {{3}}% o Poder de Ataque dos aliados contra ele.\n\n|cffffffffCombo (Talho Duplo, esta habilidade):|r ativa um |cffffffffGolpe Vil|r no alvo."}
D[64684]={"^|cff32cd32Generates 1 Felfury|r\nCharge an enemy, dealing (.-) Physical damage%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nAbalança sobre um inimigo, causando {{1}} de dano Físico."}
D[64686]={"^|cff32cd32Generates 1 Felfury|r\nStrengthen your will, reducing Physical damage taken by (.-)%% for (.-)%.\n\nWhile active, direct damaging abilities heal you for (.-)%% of your maximum health%. Can only occur once every 0%.5 sec%.%s*$","|cff32cd32Gera 1 Fúria Vil|r\nFortalece sua vontade, reduzindo o dano Físico recebido em {{1}}% durante {{2}}.\n\nEnquanto estiver ativo, as habilidades de dano direto curam você em {{3}}% de sua vida máxima. Só pode acontecer uma vez a cada 0,5 s."}
D[64687]={"^|cff32cd32Fel Empowerment Ability|r\nSpin in a fury of chaos for (.-), dealing (.-)%% Weapon Damage every (.-) sec with both weapons to up to (.-) nearby enemies%.\n\nYou can move but cannot perform any other abilities, but are immune to roots and slows and loss of control effects%. You cannot be stopped unless disarmed or killed%.\n\n|cFFFFFFFFFel Empowerment|r transforms this spell into |cFFFFFFFFFury Unleashed|r%.s:555738:0@:ext@%s*$","|cff32cd32Habilidade de Empoderamento Vil|r\nGira em uma fúria de caos durante {{1}}, causando {{2}}% de dano da arma com as duas armas a cada {{3}} s até {{4}} inimigos próximos.\n\nVocê pode se mover, mas não pode usar outras habilidades. Você fica imune a efeitos de imobilização, redução de velocidade e perda de controle. Só pode ser interrompido se for desarmado ou morto.\n\n|cFFFFFFFFEmpoderamento Vil|r transforma este feitiço em |cFFFFFFFFFúria Desolada|r"}
D[64688]={"^Spin in a fury of chaos for (.-), dealing (.-)%% Weapon Damage every (.-) sec with both weapons to up to (.-) nearby enemies%.\n\nYou can move but cannot perform any other abilities, but are immune to roots and slows and loss of control effects%. You cannot be stopped unless disarmed or killed%.\n\n|cFFFFFFFFFel Empowerment|r transforms this spell into |cFFFFFFFFFury Unleashed|r%.s:555738:0@:ext@%s*$","Gira em uma fúria de caos durante {{1}}, causando {{2}}% de dano da arma com as duas armas a cada {{3}} s até {{4}} inimigos próximos.\n\nVocê pode se mover, mas não pode usar outras habilidades. Você fica imune a efeitos de imobilização, redução de velocidade e perda de controle. Só pode ser interrompido se for desarmado ou morto.\n\n|cFFFFFFFFEmpoderamento Vil|r transforma este feitiço em |cFFFFFFFFFúria Desolada|r"}
D[64689]={"^Direct critical strikes now have a (.-)%% chance to trigger a |cffffffffFelstrike|r and generate a |cffffffffFragment of Malice|r%.%s*$","Acertos críticos diretos têm {{1}}% de chance de ativar um |cffffffffGolpe Vil|r e gerar um |cffffffffFragmento de Malícia|r."}
D[64943]={"^Take vengeance upon up to (.-) enemies in a (.-) yd frontal cone, dealing (.-) Chaos Damage and triggering 2 |cffffffffFelstrikes|r%.\n\n|cFFFFFFFF%(Combo%]|r After using |cFFFFFFFFVengeance|r: |cFFFFFFFFTwin Slice|r costs no energy%.\n\n|cFFFFFFFF%(Combo%)|r After using |cffffffffVengeance|r: |cFFFFFFFFStomp|r heals you for (.-)%% of your maximum health%.%s*$","Vinga-se sobre até {{1}} inimigos em um cone frontal de {{2}} m, causando {{3}} de dano de Caos e ativando 2 |cffffffffGolpes Demoníacos|r.\n\n|cFFFFFFFF(Combo]|r Depois de usar |cFFFFFFFFVingança|r: |cFFFFFFFFTalho Duplo|r não custa energia.\n\n|cFFFFFFFF(Combo)|r Depois de usar |cffffffffVingança|r: |cFFFFFFFFPisão|r cura você em {{4}}% de sua vida máxima."}
D[64944]={"^Take vengeance upon up to (.-) enemies in a (.-) yd frontal cone, dealing (.-) Chaos Damage and triggering 2 |cffffffffFelstrikes|r%.\n\n|cFFFFFFFF%(Combo%]|r After using |cFFFFFFFFVengeance|r: |cFFFFFFFFTwin Slice|r costs no energy%.%s*$","Vinga-se sobre até {{1}} inimigos em um cone frontal de {{2}} m, causando {{3}} de dano de Caos e ativando 2 |cffffffffGolpes Demoníacos|r.\n\n|cFFFFFFFF(Combo]|r Depois de usar |cFFFFFFFFVingança|r: |cFFFFFFFFTalho Duplo|r não custa energia."}
