D[97257]={"^Increases your chance to dodge by (.-)%%%.%s*$","Aumenta sua chance de esquiva em {{1}}%."}
D[97416]={"^Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice and Suffering spells by (.-)%%, and increases the attack power bonus on your Felguard's Demonic Frenzy effect by (.-)%%%.%s*$","aumenta em {{1}}% a eficácia dos feitiços Tormento, Consumir sombras, Sacrifício e Sofrimento de seu Emissário do Caos e aumenta o bônus de poder de ataque do efeito de Frenesi demoníaco de seu guarda vil {{2}}%."}
D[97417]={"^Increases the damage done by your Voidwalker, Succubus, Felhunter and Felguard's melee attacks and your Imp's Firebolt by (.-)%%%.%s*$","Aumenta o dano causado pelos ataques corpo a corpo de seu Emissário do Caos, súcubo, manáfago e guarda vil e o causado pela Seta de Fogo de seu diablilho {{1}}%."}
D[97734]={"^Increases the Stamina and Intellect of your Imp, Voidwalker, Succubus, Felhunter and Felguard by (.-)%% and increases your maximum health and mana by (.-)%%%.%s*$","Aumenta o vigor e o intelecto de seu diablilho, Emissário do Caos, súcubo, manáfago e guarda vil {{1}}% e aumentando sua vida e mana máximas {{2}}%."}
D[98355]={"^Your maximum health is increased by (.-)%%, and your chance to be critically hit is reduced by (.-)%%%.\n\n|cFFFFFFFFImmolation Aura|r increases the percentage of damage shared via your |cFFFFFFFFSoul Link|r by 10%% and protects you against most effects that would interrupt your ongoing spell cast%.%s*$","Seu Vida máxima aumenta {{1}}%, e sua chance de receber um acerto crítico é reduzida {{2}}%.\n\n|cFFFFFFFFAura de Imolação|r aumenta o percentual de dano compartilhado por meio de seu |cFFFFFFFFVínculo da Alma|r em 10% e proteja você contra a maioria dos efeitos que interromperiam seu lançamento de feitiço em curso."}
D[98650]={"^Activate%s+near%s+a%s+forge%s+camp%s+warp%-gate%s+to%s+possess%s+the%s+nearby%s+felguard%s+degrader%.%s*$","Ativa perto de um portal de distorção de um Acampamento Forja para possuir o degradador Guarda Vil próximo."}
D[99677]={"^Fires%s+a%s+Fel%s+Cannon%s+Mortar%s+at%s+the%s+Targetting%s+Reticle%s+from%s+the%s+nearest%s+cannon%.%s*$","Dispara um obús de canhão demoníaco ao ponto de olhe do canhão mais próximo."}
D[99893]={"^Imbues%s+the%s+target%s+with%s+nether%s+energies,%s+reinforcing%s+the%s+fel%s+infusion%.%s*$","Imbui o alvo com energias abissais, reforçando a infusão vil."}
D[102086]={"^Summons%s+a%s+Felguard%s+under%s+the%s+command%s+of%s+the%s+Warlock%.%s*$","\nEvoca um Guarda Fel sob o comando do Bruxo."}
D[102219]={"^Taunts%s+the%s+creature,%s+increasing%s+the%s+chance%s+that%s+it%s+will%s+attack%s+the%s+Felguard%.%s*$","Provoca à criatura, aumentando a chance de ataque ao guarda vil."}
D[102462]={"^Turns%s+and%s+fires%s+the%s+fel%s+cannon%s+at%s+Forge%s+Camp:%s+Fear%.%s*$","Acende e dispara o canhão vil em Acampamento Forja: medo."}
D[102463]={"^Turns%s+and%s+fires%s+the%s+fel%s+cannon%s+at%s+Forge%s+Camp:%s+Hate%.%s*$","Acende e dispara o canhão vil em Acampamento Forja: ódio."}
D[102484]={"^Unlocks%s+the%s+fel%s+cannon%s+at%s+Forge%s+Camp:%s+Fear%.%s*$","Desbloquear o canhão vil do Acampamento Forja: Medo."}
D[102485]={"^Unlocks%s+the%s+fel%s+cannon%s+at%s+Forge%s+Camp:%s+Hate%.%s*$","Desbloquear o canhão vil do Acampamento Forja: Ódio."}
D[102508]={"^Use%s+this%s+scroll%s+to%s+modify%s+the%s+appearance%s+of%s+your%s+Felguard%s+to%s+look%s+like%s+Squadron%s+Commander%s+Vishax%.%s*$","Use este pergaminho para modificar a aparência de seu Guarda Félida para que se parezca a Squadron Commander Vishax."}
D[102908]={"^Zooms%s+the%s+camera%s+in%s+to%s+the%s+nearest%s+fel%s+cannon%.%s*$","Aproxima a câmera do canhão vil mais próximo."}
