T[1226]={"^Causes (.-) Fire Damage to nearby enemies every (.-) sec%.%s*$","Causa {{1}} de dano de Fogo aos inimigos próximos a cada {{2}} s."}
T[1227]={"^Causes |cffffffffImmolation Aura|r to heal you based on the damage it deals%. The health returned is reduced based on how many enemies are stuck%.%s*$","Faz com que se ativar o |cffffffffAura de Imolação|r para curar você conforme o dano que causa. A vida devolvida é reduzido em função do número de inimigos presos."}
T[1244]={"^Casting |cff32cd32Inner Demon|r now refunds 1 |cff32cd32Felfury|r every 1 sec for 6 sec%.%s*$","Agora devolva 1 |cff32cd32Demônio Interior|r a cada 1 s durante 6 s ao lançar |cff32cd32Fúria Vil|r."}
